#!/bin/sh
# The workload for claim E3.4: what output keys cost on a *first* run — a run where nothing can be
# replayed. A real checkout for a workspace to diff, one marked step (it names a run-specific value,
# so `readsRunSpecific` makes it always-run, which is what output keys act on), and steps after it.
#
# Every step carries the trial's token, so no step is ever replayed and each trial is a first run.
# The arms are the operator's flag, RUNNER_OUTPUT_KEYS, which lives in the unit file.
set -eu
cat <<'EOF'
# Generated by measurements/e3.4/gen-workflow.sh — do not edit by hand.
name: measure-outputkeys
on:
  workflow_dispatch:
    inputs:
      token:
        description: A value new for every trial, so no step can be replayed
        required: true
jobs:
  first-run:
    runs-on: [self-hosted, zig]
    steps:
      - uses: actions/checkout@v4
        with:
          repository: go-task/task
          ref: ad2782e1709f0bcf8fbbe0d8e00c2d239141e099
      - name: Always-run step (it reads a run-specific value)
        run: ": marked for trial ${{ inputs.token }}, run $GITHUB_RUN_ID"
      - run: ": after the marked step, 1 of 3, trial ${{ inputs.token }}"
      - run: ": after the marked step, 2 of 3, trial ${{ inputs.token }}"
      - run: ": after the marked step, 3 of 3, trial ${{ inputs.token }}"
EOF
